import { useRef, useEffect } from "react";
import { setBrowserBounds, setBrowserVisible } from "../lib/browserTauri";
import { BrowserToolbar } from "./BrowserToolbar";
import type { BrowserTab } from "../lib/types";

interface BrowserPaneProps {
  tab: BrowserTab;
  visible?: boolean;
  onNavigate: (url: string) => void;
  onReload: () => void;
}

export function BrowserPane({ tab, visible = true, onNavigate, onReload }: BrowserPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const updateVisibility = (nextVisible: boolean) => {
      void setBrowserVisible(tab.browserId, nextVisible).catch(() => undefined);
    };

    const updateBounds = () => {
      if (!visible) {
        updateVisibility(false);
        return;
      }

      const rect = el.getBoundingClientRect();
      void setBrowserBounds(tab.browserId, {
        x: rect.x,
        y: rect.y,
        width: rect.width,
        height: rect.height,
      }).catch(() => undefined);
      updateVisibility(true);
    };

    updateBounds();

    const resizeObserver = new ResizeObserver(() => {
      updateBounds();
    });

    resizeObserver.observe(el);
    window.addEventListener("resize", updateBounds);

    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", updateBounds);
      // Native child webviews outlive React DOM nodes; cleanup also covers Fast Refresh remounts.
      updateVisibility(false);
    };
  }, [tab.browserId, visible]);

  return (
    <div className="flex flex-col w-full h-full bg-background overflow-hidden">
      <BrowserToolbar tab={tab} onNavigate={onNavigate} onReload={onReload} />
      <div
        ref={containerRef}
        data-testid="browser-viewport"
        className="flex-1 w-full bg-card relative"
      />
    </div>
  );
}

import { useState, useEffect } from "react";
import { ArrowLeft, ArrowRight, RotateCw, ExternalLink, ZoomIn, ZoomOut, Target, RefreshCw } from "lucide-react";
import { focusBrowser, getBrowserState, openExternalUrl, setBrowserZoom } from "../lib/browserTauri";
import type { BrowserTab } from "../lib/types";

interface BrowserToolbarProps {
  tab: BrowserTab;
  onNavigate: (url: string) => void;
  onReload: () => void;
  onGoBack?: () => void;
  onGoForward?: () => void;
}

export function BrowserToolbar({
  tab,
  onNavigate,
  onReload,
  onGoBack,
  onGoForward,
}: BrowserToolbarProps) {
  const [inputUrl, setInputUrl] = useState(tab.url);
  const [zoomFactor, setZoomFactor] = useState(1.0);

  useEffect(() => {
    setInputUrl(tab.url);
  }, [tab.url]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    let url = inputUrl.trim();
    if (!url) return;
    if (!url.startsWith("http://") && !url.startsWith("https://") && url !== "about:blank") {
      if (url.startsWith("localhost") || url.startsWith("127.0.0.1")) {
        url = `http://${url}`;
      } else {
        url = `https://${url}`;
      }
    }
    onNavigate(url);
  };

  const handleExternalOpen = () => {
    if (tab.url && tab.url !== "about:blank") {
      void openExternalUrl(tab.url);
    }
  };

  const handleZoomIn = async () => {
    const nextZoom = Math.min(2.0, Math.round((zoomFactor + 0.1) * 10) / 10);
    setZoomFactor(nextZoom);
    try {
      await setBrowserZoom(tab.browserId, nextZoom);
    } catch {
      // ignore
    }
  };

  const handleZoomOut = async () => {
    const nextZoom = Math.max(0.5, Math.round((zoomFactor - 0.1) * 10) / 10);
    setZoomFactor(nextZoom);
    try {
      await setBrowserZoom(tab.browserId, nextZoom);
    } catch {
      // ignore
    }
  };

  const handleFocus = async () => {
    try {
      await focusBrowser(tab.browserId);
    } catch {
      // ignore
    }
  };

  const handleSyncState = async () => {
    try {
      const state = await getBrowserState(tab.browserId);
      if (state.url && state.url !== inputUrl) {
        setInputUrl(state.url);
      }
    } catch {
      // ignore
    }
  };

  return (
    <div className="flex items-center gap-2 px-3 py-1.5 bg-sidebar border-b border-border text-xs text-foreground select-none">
      <div className="flex items-center gap-1">
        <button
          type="button"
          disabled={!tab.canGoBack}
          onClick={onGoBack}
          aria-label="Back"
          className="p-1 rounded hover:bg-muted disabled:opacity-30 transition-colors"
        >
          <ArrowLeft className="w-3.5 h-3.5" />
        </button>
        <button
          type="button"
          disabled={!tab.canGoForward}
          onClick={onGoForward}
          aria-label="Forward"
          className="p-1 rounded hover:bg-muted disabled:opacity-30 transition-colors"
        >
          <ArrowRight className="w-3.5 h-3.5" />
        </button>
        <button
          type="button"
          onClick={onReload}
          aria-label="Reload"
          className="p-1 rounded hover:bg-muted transition-colors"
        >
          <RotateCw className={`w-3.5 h-3.5 ${tab.loading ? "animate-spin" : ""}`} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex items-center">
        <input
          type="text"
          value={inputUrl}
          onChange={(e) => setInputUrl(e.target.value)}
          placeholder="Search or enter URL"
          aria-label="URL address bar"
          className="w-full bg-background border border-border rounded px-2.5 py-1 text-xs text-foreground focus:outline-none focus:border-primary font-mono"
        />
      </form>

      <div className="flex items-center gap-0.5 border-l border-border/70 pl-1.5">
        <button
          type="button"
          onClick={handleZoomOut}
          title="Zoom out"
          aria-label="Zoom out"
          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
        >
          <ZoomOut className="w-3.5 h-3.5" />
        </button>
        <span className="font-mono text-[10px] text-muted-foreground w-8 text-center">
          {Math.round(zoomFactor * 100)}%
        </span>
        <button
          type="button"
          onClick={handleZoomIn}
          title="Zoom in"
          aria-label="Zoom in"
          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
        >
          <ZoomIn className="w-3.5 h-3.5" />
        </button>
      </div>

      <div className="flex items-center gap-0.5 border-l border-border/70 pl-1.5">
        <button
          type="button"
          onClick={handleFocus}
          title="Focus webview"
          aria-label="Focus webview"
          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
        >
          <Target className="w-3.5 h-3.5" />
        </button>
        <button
          type="button"
          onClick={handleSyncState}
          title="Sync browser state"
          aria-label="Sync browser state"
          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
        >
          <RefreshCw className="w-3.5 h-3.5" />
        </button>
        <button
          type="button"
          onClick={handleExternalOpen}
          title="Open in default browser"
          aria-label="Open in external browser"
          className="p-1 rounded hover:bg-muted transition-colors"
        >
          <ExternalLink className="w-3.5 h-3.5 text-muted-foreground" />
        </button>
      </div>
    </div>
  );
}

import { open } from "@tauri-apps/plugin-dialog";
import { FolderGit2, FolderPlus, GitBranch, LoaderCircle, X } from "lucide-react";
import { FormEvent, useEffect, useRef, useState } from "react";

import {
  createWorktree,
  isTauriRuntime,
  listProjectBranches,
  registerProject,
