import { AlertTriangle, GitBranch, Trash2, X } from "lucide-react";
import { useEffect, useMemo, useState } from "react";

import {
  DEFAULT_WORKSPACE_ID,
  deleteWorktree,
  deleteWorktreeDestructive,
  previewWorktreeDelete,
  toIpcError,
} from "../lib/tauri";
import { worktreeIdentity, type BranchDeletionPreview, type StructuredIpcError, type Worktree } from "../lib/types";

export type WorktreeDeleteServices = {
  previewDelete: (worktree: Worktree) => Promise<BranchDeletionPreview>;
  deleteSafe: (worktree: Worktree) => Promise<void>;
  deleteDestructive: (worktree: Worktree) => Promise<void>;
};

type WorktreeDeleteDialogProps = {
  workspaceId?: string;
  worktree: Worktree;
  onClose: () => void;
  onDeleted: () => void;
  services?: WorktreeDeleteServices;
};

function createDefaultServices(workspaceId: string): WorktreeDeleteServices {
  return {
    previewDelete: async (worktree) => {
      const identity = requireIdentity(worktree);
      return previewWorktreeDelete({ workspaceId, worktree: identity });
    },
    deleteSafe: async (worktree) => {
      const identity = requireIdentity(worktree);
      await deleteWorktree({ workspaceId, worktree: identity, deleteBranch: true });
    },
    deleteDestructive: async (worktree) => {
      const identity = requireIdentity(worktree);
      await deleteWorktreeDestructive({ workspaceId, worktree: identity, deleteBranch: true });
    },
  };
}

export function WorktreeDeleteDialog({
  workspaceId = DEFAULT_WORKSPACE_ID,
  worktree,
  onClose,
  onDeleted,
  services,
}: WorktreeDeleteDialogProps) {
  const resolvedServices = useMemo(() => services ?? createDefaultServices(workspaceId), [services, workspaceId]);
  const [preview, setPreview] = useState<BranchDeletionPreview | null>(null);
  const [error, setError] = useState<StructuredIpcError | null>(null);
  const [destructiveRequired, setDestructiveRequired] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setPreview(null);
    setError(null);
    setDestructiveRequired(false);
    setBusy(true);
    void resolvedServices
      .previewDelete(worktree)
      .then((result) => {
        if (!cancelled) setPreview(result);
      })
      .catch((cause) => {
        if (!cancelled) setError(toIpcError(cause));
      })
      .finally(() => {
        if (!cancelled) setBusy(false);
      });
    return () => {
      cancelled = true;
    };
  }, [resolvedServices, worktree]);

  const finishDelete = () => {
    onDeleted();
    onClose();
  };

  const handleSafeDelete = async () => {
    setBusy(true);
    setError(null);
    try {
      await resolvedServices.deleteSafe(worktree);
      finishDelete();
    } catch (cause) {
      const ipcError = toIpcError(cause);
      setError(ipcError);
      setDestructiveRequired(ipcError.code === "UNMERGED_BRANCH");
    } finally {
      setBusy(false);
    }
  };

  const handleDestructiveDelete = async () => {
    setBusy(true);
    setError(null);
    try {
      await resolvedServices.deleteDestructive(worktree);
      finishDelete();
    } catch (cause) {
      setError(toIpcError(cause));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm" onMouseDown={onClose}>
      <div
        role="dialog"
        aria-label="Delete worktree"
        aria-modal="true"
        className="w-full max-w-lg animate-enter overflow-hidden rounded-xl border border-border bg-card shadow-2xl"
        onMouseDown={(event) => event.stopPropagation()}
      >
        <header className="flex items-center justify-between border-b border-border px-4 py-3">
          <div className="flex items-center gap-2 text-sm font-semibold text-foreground">
            <Trash2 className="size-4 text-destructive" />
            Delete worktree
          </div>
          <button type="button" onClick={onClose} aria-label="Close delete dialog" className="rounded-md p-1 text-muted-foreground hover:bg-accent hover:text-foreground">
            <X className="size-4" />
          </button>
        </header>

        <div className="space-y-4 p-4 text-xs">
          <p className="text-muted-foreground">
            Review the branch state before deleting <span className="font-mono text-foreground">{worktree.path}</span>.
          </p>

          {busy && !preview ? <div className="rounded-md border border-border bg-background/50 px-3 py-4 text-muted-foreground">Loading deletion preview…</div> : null}

          {preview ? (
            <div className="overflow-hidden rounded-lg border border-border bg-background/45">
              <PreviewRow label="Branch" value={preview.branch} icon={<GitBranch className="size-3" />} />
              <PreviewRow label="HEAD" value={preview.head} mono />
              <PreviewRow label="Upstream" value={preview.upstream ?? "None"} />
              <PreviewRow label="Merge state" value={preview.merged ? "Merged" : "Not merged"} />
              <PreviewRow label="Divergence" value={`${preview.ahead ?? "?"} ahead · ${preview.behind ?? "?"} behind`} />
            </div>
          ) : null}

          {destructiveRequired ? (
            <div className="space-y-2 rounded-lg border border-destructive/35 bg-destructive/10 p-3">
              <div className="flex items-start gap-2 text-destructive">
                <AlertTriangle className="mt-0.5 size-4 shrink-0" />
                <div>
                  <div className="font-semibold">Unmerged branch</div>
                  <p className="mt-1 text-[11px] leading-relaxed text-destructive/85">
                    Safe deletion refused to discard unmerged commits. Destructive deletion is a separate explicit action.
                  </p>
                </div>
              </div>
              <button
                type="button"
                disabled={busy}
                onClick={() => void handleDestructiveDelete()}
                className="w-full rounded-md bg-destructive px-3 py-2 font-semibold text-destructive-foreground disabled:opacity-50"
              >
                Delete unmerged branch permanently
              </button>
            </div>
          ) : null}

          {error && !destructiveRequired ? (
            <div className="rounded-md border border-destructive/30 bg-destructive/10 px-3 py-2 text-destructive">
              <div className="font-semibold">{error.code}</div>
              <div className="mt-0.5 text-[11px]">{error.message}</div>
            </div>
          ) : null}

          <div className="flex justify-end gap-2">
            <button type="button" onClick={onClose} className="rounded-md px-3 py-2 text-muted-foreground hover:bg-accent hover:text-foreground">
              Cancel
            </button>
            {!destructiveRequired ? (
              <button
                type="button"
                disabled={busy || !preview}
                onClick={() => void handleSafeDelete()}
                className="rounded-md bg-destructive px-3 py-2 font-semibold text-destructive-foreground disabled:opacity-50"
              >
                Delete worktree and branch
              </button>
            ) : null}
          </div>
        </div>
      </div>
    </div>
  );
}

function PreviewRow({ label, value, mono = false, icon }: { label: string; value: string; mono?: boolean; icon?: React.ReactNode }) {
  return (
    <div className="flex items-center gap-3 border-b border-border px-3 py-2 last:border-b-0">
      <span className="flex w-24 shrink-0 items-center gap-1 text-muted-foreground">{icon}{label}</span>
      <span className={`min-w-0 flex-1 truncate text-right text-foreground ${mono ? "font-mono" : ""}`}>{value}</span>
    </div>
  );
}

function requireIdentity(worktree: Worktree) {
  const identity = worktreeIdentity(worktree);
  if (identity) return identity;
  throw {
    code: "INVALID_NAMESPACE",
    message: "Only Orca-managed worktrees can be deleted from this UI.",
    details: { path: worktree.path },
  } satisfies StructuredIpcError;
}

import {
  ArrowDown,
  ArrowLeft,
  ArrowRight,
  ArrowUp,
  SlidersHorizontal,
} from "lucide-react";
import React, { useState } from "react";

type MobileKeyDockProps = {
  onSendKey: (key: string) => void;
};

export const MobileKeyDock: React.FC<MobileKeyDockProps> = ({ onSendKey }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [ctrlLatched, setCtrlLatched] = useState(false);
  const [altLatched, setAltLatched] = useState(false);

  const triggerKey = (action: string) => {
    // Haptic vibration if supported
    if ("vibrate" in navigator) {
      try {
        navigator.vibrate(15);
      } catch {
        // ignore
      }
    }

    if (action === "ctrl") {
      setCtrlLatched(!ctrlLatched);
      return;
    }
    if (action === "alt") {
      setAltLatched(!altLatched);
      return;
    }

    let finalAction = action;
    if (ctrlLatched) {
      finalAction = `ctrl-${action}`;
      setCtrlLatched(false);
    } else if (altLatched) {
      finalAction = `alt-${action}`;
      setAltLatched(false);
    }

    onSendKey(finalAction);
  };

  return (
    <div className="w-full bg-card border-t border-border select-none touch-manipulation z-30">
      {/* Expanded utility row */}
      {isExpanded && (
        <div className="flex gap-1.5 px-2 pt-2 pb-1 overflow-x-auto no-scrollbar text-xs font-mono">
          <KeyButton label="~" onClick={() => triggerKey("~")} />
          <KeyButton label="`" onClick={() => triggerKey("`")} />
          <KeyButton label="|" onClick={() => triggerKey("|")} />
          <KeyButton label="/" onClick={() => triggerKey("/")} />
          <KeyButton label="\" onClick={() => triggerKey("\\")} />
          <KeyButton label="-" onClick={() => triggerKey("-")} />
          <KeyButton label="_" onClick={() => triggerKey("_")} />
          <KeyButton label="=" onClick={() => triggerKey("=")} />
          <KeyButton label="PgUp" onClick={() => triggerKey("pageup")} />
          <KeyButton label="PgDn" onClick={() => triggerKey("pagedown")} />
          <KeyButton label="Home" onClick={() => triggerKey("home")} />
          <KeyButton label="End" onClick={() => triggerKey("end")} />
          <KeyButton label="Ctrl-Z" onClick={() => triggerKey("ctrl-z")} />
          <KeyButton label="Ctrl-D" onClick={() => triggerKey("ctrl-d")} />
        </div>
      )}

      {/* Primary essential row */}
      <div className="flex items-center justify-between gap-1 px-2 py-1.5 overflow-x-auto no-scrollbar">
        <div className="flex items-center gap-1.5">
          <KeyButton
            label="Ctrl"
            active={ctrlLatched}
            onClick={() => triggerKey("ctrl")}
            className="font-semibold"
          />
          <KeyButton
            label="Alt"
            active={altLatched}
            onClick={() => triggerKey("alt")}
            className="font-semibold"
          />
          <KeyButton label="Esc" onClick={() => triggerKey("esc")} />
          <KeyButton label="Tab" onClick={() => triggerKey("tab")} />
          <KeyButton
            label="Ctrl-C"
            highlight
            onClick={() => triggerKey("ctrl-c")}
            className="font-bold text-destructive-foreground border-destructive/50 bg-destructive/20"
          />
        </div>

        <div className="flex items-center gap-1">
          <KeyButton icon={<ArrowLeft size={14} />} onClick={() => triggerKey("left")} />
          <KeyButton icon={<ArrowUp size={14} />} onClick={() => triggerKey("up")} />
          <KeyButton icon={<ArrowDown size={14} />} onClick={() => triggerKey("down")} />
          <KeyButton icon={<ArrowRight size={14} />} onClick={() => triggerKey("right")} />
          <KeyButton
            icon={<SlidersHorizontal size={13} />}
            active={isExpanded}
            onClick={() => setIsExpanded(!isExpanded)}
            title="More keys"
          />
        </div>
      </div>
    </div>
  );
};

function KeyButton({
  label,
  icon,
  active,
  highlight,
  onClick,
  className = "",
  title,
}: {
  label?: string;
  icon?: React.ReactNode;
  active?: boolean;
  highlight?: boolean;
  onClick: () => void;
  className?: string;
  title?: string;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      title={title}
      className={`min-w-[38px] h-8 px-2 flex items-center justify-center rounded border text-xs font-mono font-medium transition-all active:scale-95 ${
        active
          ? "bg-primary border-primary text-primary-foreground shadow-sm"
          : highlight
          ? "border-border text-foreground bg-secondary hover:bg-secondary/80"
          : "bg-secondary/60 border-border text-foreground hover:bg-secondary hover:text-foreground"
      } ${className}`}
    >
      {icon || label}
    </button>
  );
}

import { useCallback, useEffect, useState } from "react";

import { APPEARANCE_SETTINGS_STORAGE_KEY } from "./storageKeys";

export type AppearanceTheme = "charcoal" | "dark" | "light" | "system";
export type AppearanceAccent = "default" | "blue" | "emerald" | "purple" | "amber" | "rose";
export type AppearanceDensity = "compact" | "comfortable";

export type AppearanceSettingsState = {
  theme: AppearanceTheme;
  accentColor: AppearanceAccent;
  density: AppearanceDensity;
};

export const DEFAULT_APPEARANCE_SETTINGS: AppearanceSettingsState = {
  theme: "charcoal",
  accentColor: "default",
  density: "compact",
};

export const APPEARANCE_SETTINGS_EVENT = "ferryx:appearance-settings";

const THEMES = new Set<AppearanceTheme>(["charcoal", "dark", "light", "system"]);
const ACCENTS = new Set<AppearanceAccent>(["default", "blue", "emerald", "purple", "amber", "rose"]);
const DENSITIES = new Set<AppearanceDensity>(["compact", "comfortable"]);

function browserStorage(): Storage | null {
  if (typeof window === "undefined") return null;
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

function normalizeAppearanceSettings(value: unknown): AppearanceSettingsState {
  const source = value && typeof value === "object" ? (value as Partial<AppearanceSettingsState>) : {};
  return {
    theme: typeof source.theme === "string" && THEMES.has(source.theme as AppearanceTheme)
      ? (source.theme as AppearanceTheme)
      : DEFAULT_APPEARANCE_SETTINGS.theme,
    accentColor: typeof source.accentColor === "string" && ACCENTS.has(source.accentColor as AppearanceAccent)
      ? (source.accentColor as AppearanceAccent)
      : DEFAULT_APPEARANCE_SETTINGS.accentColor,
    density: typeof source.density === "string" && DENSITIES.has(source.density as AppearanceDensity)
      ? (source.density as AppearanceDensity)
      : DEFAULT_APPEARANCE_SETTINGS.density,
  };
}

export function loadAppearanceSettings(storage: Storage | null = browserStorage()): AppearanceSettingsState {
  if (!storage) return { ...DEFAULT_APPEARANCE_SETTINGS };
  try {
    const raw = storage.getItem(APPEARANCE_SETTINGS_STORAGE_KEY);
    if (!raw) return { ...DEFAULT_APPEARANCE_SETTINGS };
    return normalizeAppearanceSettings(JSON.parse(raw));
  } catch {
    return { ...DEFAULT_APPEARANCE_SETTINGS };
  }
}

export function saveAppearanceSettings(
  patch: Partial<AppearanceSettingsState>,
  storage: Storage | null = browserStorage(),
): AppearanceSettingsState {
  const next = normalizeAppearanceSettings({ ...loadAppearanceSettings(storage), ...patch });
  try {
    storage?.setItem(APPEARANCE_SETTINGS_STORAGE_KEY, JSON.stringify(next));
  } catch {
    // Keep in-memory state usable even if storage is unavailable.
  }
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent<AppearanceSettingsState>(APPEARANCE_SETTINGS_EVENT, { detail: next }));
  }
  return next;
}

export function resetAppearanceSettings(storage: Storage | null = browserStorage()): AppearanceSettingsState {
  try {
    storage?.removeItem(APPEARANCE_SETTINGS_STORAGE_KEY);
  } catch {
    // ignore storage failures
  }
  const next = { ...DEFAULT_APPEARANCE_SETTINGS };
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent<AppearanceSettingsState>(APPEARANCE_SETTINGS_EVENT, { detail: next }));
  }
  return next;
}

function resolvedTheme(theme: AppearanceTheme): Exclude<AppearanceTheme, "system"> {
  if (theme !== "system") return theme;
  if (typeof window !== "undefined" && typeof window.matchMedia === "function") {
    return window.matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark";
  }
  return "dark";
}

export function applyAppearanceSettings(
  settings: AppearanceSettingsState,
  root: HTMLElement | null = typeof document !== "undefined" ? document.documentElement : null,
) {
  if (!root) return;
  const theme = resolvedTheme(settings.theme);
  root.dataset.theme = theme;
  root.dataset.themePreference = settings.theme;
  root.dataset.accent = settings.accentColor;
  root.dataset.density = settings.density;
  root.style.colorScheme = theme === "light" ? "light" : "dark";
}

export function useAppearanceSettings() {
  const [settings, setSettings] = useState<AppearanceSettingsState>(loadAppearanceSettings);

  useEffect(() => {
    const sync = (event: Event) => {
      const detail = (event as CustomEvent<AppearanceSettingsState>).detail;
      setSettings(detail ? normalizeAppearanceSettings(detail) : loadAppearanceSettings());
    };
    const storage = (event: StorageEvent) => {
      if (event.key === APPEARANCE_SETTINGS_STORAGE_KEY) setSettings(loadAppearanceSettings());
    };
    window.addEventListener(APPEARANCE_SETTINGS_EVENT, sync);
    window.addEventListener("storage", storage);
    return () => {
      window.removeEventListener(APPEARANCE_SETTINGS_EVENT, sync);
      window.removeEventListener("storage", storage);
    };
  }, []);

  const updateSettings = useCallback((patch: Partial<AppearanceSettingsState>) => {
    const next = saveAppearanceSettings(patch);
    setSettings(next);
    return next;
  }, []);

  const resetSettings = useCallback(() => {
    const next = resetAppearanceSettings();
    setSettings(next);
    return next;
  }, []);

  return { settings, updateSettings, resetSettings };
}

export function useApplyAppearanceSettings() {
  const { settings } = useAppearanceSettings();

  useEffect(() => {
    applyAppearanceSettings(settings);
    if (settings.theme !== "system" || typeof window.matchMedia !== "function") return;
    const query = window.matchMedia("(prefers-color-scheme: light)");
    const handleChange = () => applyAppearanceSettings(settings);
    query.addEventListener?.("change", handleChange);
    return () => query.removeEventListener?.("change", handleChange);
  }, [settings]);

  return settings;
}

import { useCallback, useEffect, useState } from "react";

import { BROWSER_SETTINGS_STORAGE_KEY } from "./storageKeys";

export type BrowserSearchEngine = "duckduckgo" | "google" | "bing" | "brave";

export type BrowserProfile = {
  id: string;
  name: string;
};

export type BrowserSettingsState = {
  homePage: string;
  searchEngine: BrowserSearchEngine;
  defaultZoom: number;
  restoreTabsOnLaunch: boolean;
  openLinksInBuiltInBrowser: boolean;
  shiftOpensSystemBrowser: boolean;
  showTerminalLinkActions: boolean;
  localhostWorktreeLabels: boolean;
  profiles: BrowserProfile[];
  defaultProfileId: string;
};

export const DEFAULT_BROWSER_PROFILE: BrowserProfile = { id: "default", name: "Default" };

export const DEFAULT_BROWSER_SETTINGS: BrowserSettingsState = {
  homePage: "",
  searchEngine: "duckduckgo",
  defaultZoom: 100,
  restoreTabsOnLaunch: false,
  openLinksInBuiltInBrowser: true,
  shiftOpensSystemBrowser: true,
  showTerminalLinkActions: true,
  localhostWorktreeLabels: true,
  profiles: [DEFAULT_BROWSER_PROFILE],
  defaultProfileId: DEFAULT_BROWSER_PROFILE.id,
};

export const BROWSER_SETTINGS_EVENT = "ferryx:browser-settings";

const SEARCH_ENGINES = new Set<BrowserSearchEngine>(["duckduckgo", "google", "bing", "brave"]);
export const BROWSER_ZOOM_LEVELS = [75, 80, 90, 100, 110, 125, 150, 175, 200] as const;
const ZOOM_LEVELS = new Set<number>(BROWSER_ZOOM_LEVELS);
const PROFILE_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;

function browserStorage(): Storage | null {
  if (typeof window === "undefined") return null;
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

function normalizeProfile(input: unknown): BrowserProfile | null {
  if (!input || typeof input !== "object") return null;
  const source = input as Partial<BrowserProfile>;
  const id = typeof source.id === "string" ? source.id.trim() : "";
  const name = typeof source.name === "string" ? source.name.trim() : "";
  if (!PROFILE_ID_PATTERN.test(id) || !name) return null;
  return { id, name: name.slice(0, 80) };
}

function normalizeProfiles(value: unknown): BrowserProfile[] {
  const normalized: BrowserProfile[] = [];
  const seen = new Set<string>();
  if (Array.isArray(value)) {
    for (const candidate of value) {
      const profile = normalizeProfile(candidate);
      if (!profile || seen.has(profile.id)) continue;
      seen.add(profile.id);
      normalized.push(profile);
    }
  }
  if (!seen.has(DEFAULT_BROWSER_PROFILE.id)) normalized.unshift(DEFAULT_BROWSER_PROFILE);
  return normalized.length > 0 ? normalized : [DEFAULT_BROWSER_PROFILE];
}

export function normalizeHomePageInput(input: string): string {
  const trimmed = input.trim();
  if (!trimmed) return "";
  if (/\s/.test(trimmed)) throw new Error("Home page must be a URL without spaces.");
  const localhostInput = /^(?:localhost|127\.0\.0\.1)(?::\d+)?(?:\/|$)/i.test(trimmed);
  if (!localhostInput && /^[A-Za-z][A-Za-z0-9+.-]*:/.test(trimmed) && !/^https?:\/\//i.test(trimmed)) {
    throw new Error("Home page must use http:// or https://.");
  }

  const withScheme = /^(?:https?):\/\//i.test(trimmed)
    ? trimmed
    : localhostInput
      ? `http://${trimmed}`
      : `https://${trimmed}`;

  let parsed: URL;
  try {
    parsed = new URL(withScheme);
  } catch {
    throw new Error("Enter a valid http(s) URL.");
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new Error("Home page must use http:// or https://.");
  }
  return parsed.toString();
}

export function normalizeBrowserSettings(value: unknown): BrowserSettingsState {
  const source = value && typeof value === "object" ? (value as Partial<BrowserSettingsState>) : {};
  const zoom = typeof source.defaultZoom === "number" && Number.isFinite(source.defaultZoom)
    ? Math.round(source.defaultZoom)
    : DEFAULT_BROWSER_SETTINGS.defaultZoom;
  const profiles = normalizeProfiles(source.profiles);
  const profileIds = new Set(profiles.map((profile) => profile.id));
  const requestedDefault = typeof source.defaultProfileId === "string" ? source.defaultProfileId : "";
  let homePage = DEFAULT_BROWSER_SETTINGS.homePage;
  if (typeof source.homePage === "string") {
    try {
      homePage = normalizeHomePageInput(source.homePage);
    } catch {
      homePage = DEFAULT_BROWSER_SETTINGS.homePage;
    }
  }

  return {
    homePage,
    searchEngine: typeof source.searchEngine === "string" && SEARCH_ENGINES.has(source.searchEngine as BrowserSearchEngine)
      ? (source.searchEngine as BrowserSearchEngine)
      : DEFAULT_BROWSER_SETTINGS.searchEngine,
    defaultZoom: ZOOM_LEVELS.has(zoom) ? zoom : DEFAULT_BROWSER_SETTINGS.defaultZoom,
    restoreTabsOnLaunch: typeof source.restoreTabsOnLaunch === "boolean"
      ? source.restoreTabsOnLaunch
      : DEFAULT_BROWSER_SETTINGS.restoreTabsOnLaunch,
    openLinksInBuiltInBrowser: typeof source.openLinksInBuiltInBrowser === "boolean"
      ? source.openLinksInBuiltInBrowser
      : DEFAULT_BROWSER_SETTINGS.openLinksInBuiltInBrowser,
    shiftOpensSystemBrowser: typeof source.shiftOpensSystemBrowser === "boolean"
      ? source.shiftOpensSystemBrowser
      : DEFAULT_BROWSER_SETTINGS.shiftOpensSystemBrowser,
    showTerminalLinkActions: typeof source.showTerminalLinkActions === "boolean"
      ? source.showTerminalLinkActions
      : DEFAULT_BROWSER_SETTINGS.showTerminalLinkActions,
    localhostWorktreeLabels: typeof source.localhostWorktreeLabels === "boolean"
      ? source.localhostWorktreeLabels
      : DEFAULT_BROWSER_SETTINGS.localhostWorktreeLabels,
    profiles,
    defaultProfileId: profileIds.has(requestedDefault) ? requestedDefault : DEFAULT_BROWSER_PROFILE.id,
  };
}

function settingsForPersistence(settings: BrowserSettingsState): Partial<BrowserSettingsState> {
  const persisted: Partial<BrowserSettingsState> = {};
  const scalarKeys: Array<Exclude<keyof BrowserSettingsState, "profiles">> = [
    "homePage",
    "searchEngine",
    "defaultZoom",
    "restoreTabsOnLaunch",
    "openLinksInBuiltInBrowser",
    "shiftOpensSystemBrowser",
    "showTerminalLinkActions",
    "localhostWorktreeLabels",
    "defaultProfileId",
  ];
  for (const key of scalarKeys) {
    if (settings[key] !== DEFAULT_BROWSER_SETTINGS[key]) {
      (persisted as Record<string, unknown>)[key] = settings[key];
    }
  }
  if (JSON.stringify(settings.profiles) !== JSON.stringify(DEFAULT_BROWSER_SETTINGS.profiles)) {
    persisted.profiles = settings.profiles;
  }
  return persisted;
}

export function loadBrowserSettings(storage: Storage | null = browserStorage()): BrowserSettingsState {
  if (!storage) return normalizeBrowserSettings(DEFAULT_BROWSER_SETTINGS);
  try {
    const raw = storage.getItem(BROWSER_SETTINGS_STORAGE_KEY);
    return raw ? normalizeBrowserSettings(JSON.parse(raw)) : normalizeBrowserSettings(DEFAULT_BROWSER_SETTINGS);
  } catch {
    return normalizeBrowserSettings(DEFAULT_BROWSER_SETTINGS);
  }
}

export function saveBrowserSettings(
  patch: Partial<BrowserSettingsState>,
  storage: Storage | null = browserStorage(),
): BrowserSettingsState {
  const next = normalizeBrowserSettings({ ...loadBrowserSettings(storage), ...patch });
  try {
    storage?.setItem(BROWSER_SETTINGS_STORAGE_KEY, JSON.stringify(settingsForPersistence(next)));
  } catch {
    // ignore storage failures
  }
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent<BrowserSettingsState>(BROWSER_SETTINGS_EVENT, { detail: next }));
  }
  return next;
}

export function resetBrowserSettings(storage: Storage | null = browserStorage()): BrowserSettingsState {
  try {
    storage?.removeItem(BROWSER_SETTINGS_STORAGE_KEY);
  } catch {
    // ignore
  }
  const next = normalizeBrowserSettings(DEFAULT_BROWSER_SETTINGS);
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent<BrowserSettingsState>(BROWSER_SETTINGS_EVENT, { detail: next }));
  }
  return next;
}

export function searchUrlFor(engine: BrowserSearchEngine, query: string): string {
  const encoded = encodeURIComponent(query.trim());
  switch (engine) {
    case "google":
      return `https://www.google.com/search?q=${encoded}`;
    case "bing":
      return `https://www.bing.com/search?q=${encoded}`;
    case "brave":
      return `https://search.brave.com/search?q=${encoded}`;
    case "duckduckgo":
    default:
      return `https://duckduckgo.com/?q=${encoded}`;
  }
}

export function normalizeBrowserAddress(
  input: string,
  settings: BrowserSettingsState = loadBrowserSettings(),
): string {
  const trimmed = input.trim();
  if (!trimmed) return "about:blank";
  if (trimmed === "about:blank" || trimmed.startsWith("http://") || trimmed.startsWith("https://")) return trimmed;
  if (trimmed.startsWith("localhost") || trimmed.startsWith("127.0.0.1")) return `http://${trimmed}`;

  const looksLikeHost = trimmed.includes(".") && !/\s/.test(trimmed);
  if (looksLikeHost) return `https://${trimmed}`;
  return searchUrlFor(settings.searchEngine, trimmed);
}

export function newBrowserTabUrl(settings: BrowserSettingsState = loadBrowserSettings()): string {
  return settings.homePage || "about:blank";
}

export function isHttpUrl(url: string): boolean {
  return /^https?:\/\//i.test(url.trim());
}

export function isLocalhostUrl(url: string): boolean {
  try {
    const parsed = new URL(url);
    return parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1";
  } catch {
    return false;
  }
}

export function formatBrowserTabLabel(
  baseLabel: string,
  url: string,
  worktreeLabel: string | null | undefined,
  settings: BrowserSettingsState = loadBrowserSettings(),
): string {
  if (!settings.localhostWorktreeLabels || !worktreeLabel || !isLocalhostUrl(url)) return baseLabel;
  return `${baseLabel} · ${worktreeLabel}`;
}

export function makeBrowserProfileId(name: string, profiles: BrowserProfile[]): string {
  const stem = name
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/g, "-")
    .replace(/^[^a-z0-9]+/, "")
    .slice(0, 40) || "profile";
  const ids = new Set(profiles.map((profile) => profile.id));
  if (!ids.has(stem) && stem !== DEFAULT_BROWSER_PROFILE.id) return stem;
  for (let index = 2; index < 10_000; index += 1) {
    const candidate = `${stem}-${index}`.slice(0, 64);
    if (!ids.has(candidate)) return candidate;
  }
  return `profile-${Date.now()}`;
}

export function useBrowserSettings() {
  const [settings, setSettings] = useState<BrowserSettingsState>(loadBrowserSettings);

  useEffect(() => {
    const sync = (event: Event) => {
      const detail = (event as CustomEvent<BrowserSettingsState>).detail;
      setSettings(detail ? normalizeBrowserSettings(detail) : loadBrowserSettings());
    };
    const storage = (event: StorageEvent) => {
      if (event.key === BROWSER_SETTINGS_STORAGE_KEY) setSettings(loadBrowserSettings());
    };
    window.addEventListener(BROWSER_SETTINGS_EVENT, sync);
    window.addEventListener("storage", storage);
    return () => {
      window.removeEventListener(BROWSER_SETTINGS_EVENT, sync);
      window.removeEventListener("storage", storage);
    };
  }, []);

  const updateSettings = useCallback((patch: Partial<BrowserSettingsState>) => {
    const next = saveBrowserSettings(patch);
    setSettings(next);
    return next;
  }, []);

  const resetSettings = useCallback(() => {
    const next = resetBrowserSettings();
    setSettings(next);
    return next;
  }, []);

  return { settings, updateSettings, resetSettings };
}

import { useCallback, useEffect, useState } from "react";

import { getMigratedItem, NOTIFICATION_SETTINGS_STORAGE_KEY } from "./storageKeys";

export interface NotificationSettings {
  enabled: boolean;
  agentTaskComplete: boolean;
  terminalBell: boolean;
  customSoundId: "system" | "none" | "custom" | string;
  customSoundPath: string | null;
  customSoundVolume: number;
}

export { NOTIFICATION_SETTINGS_STORAGE_KEY };
export const NOTIFICATION_SETTINGS_EVENT = "rorca:notifications:settings-changed";

export const DEFAULT_NOTIFICATION_SETTINGS: NotificationSettings = {
  enabled: true,
  agentTaskComplete: true,
  terminalBell: false,
  customSoundId: "system",
  customSoundPath: null,
  customSoundVolume: 0.8,
};

export function loadNotificationSettings(): NotificationSettings {
  if (typeof window === "undefined" || !window.localStorage) {
    return { ...DEFAULT_NOTIFICATION_SETTINGS };
  }
  try {
    const raw = getMigratedItem(NOTIFICATION_SETTINGS_STORAGE_KEY);
    if (!raw) return { ...DEFAULT_NOTIFICATION_SETTINGS };
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return { ...DEFAULT_NOTIFICATION_SETTINGS };
    return {
      enabled: typeof parsed.enabled === "boolean" ? parsed.enabled : DEFAULT_NOTIFICATION_SETTINGS.enabled,
      agentTaskComplete: typeof parsed.agentTaskComplete === "boolean" ? parsed.agentTaskComplete : DEFAULT_NOTIFICATION_SETTINGS.agentTaskComplete,
      terminalBell: typeof parsed.terminalBell === "boolean" ? parsed.terminalBell : DEFAULT_NOTIFICATION_SETTINGS.terminalBell,
      customSoundId: typeof parsed.customSoundId === "string" ? parsed.customSoundId : DEFAULT_NOTIFICATION_SETTINGS.customSoundId,
      customSoundPath: typeof parsed.customSoundPath === "string" ? parsed.customSoundPath : null,
      customSoundVolume: typeof parsed.customSoundVolume === "number" ? Math.max(0, Math.min(1, parsed.customSoundVolume)) : DEFAULT_NOTIFICATION_SETTINGS.customSoundVolume,
    };
  } catch {
    return { ...DEFAULT_NOTIFICATION_SETTINGS };
  }
}

export function saveNotificationSettings(settings: Partial<NotificationSettings>): NotificationSettings {
  const current = loadNotificationSettings();
  const next: NotificationSettings = {
    ...current,
    ...settings,
    customSoundVolume: typeof settings.customSoundVolume === "number"
      ? Math.max(0, Math.min(1, settings.customSoundVolume))
      : current.customSoundVolume,
  };
  if (typeof window !== "undefined" && window.localStorage) {
    try {
      localStorage.setItem(NOTIFICATION_SETTINGS_STORAGE_KEY, JSON.stringify(next));
      window.dispatchEvent(new CustomEvent(NOTIFICATION_SETTINGS_EVENT, { detail: next }));
    } catch {
      // ignore
    }
  }
  return next;
}

export function resetNotificationSettings(): NotificationSettings {
  if (typeof window !== "undefined" && window.localStorage) {
    try {
      localStorage.removeItem(NOTIFICATION_SETTINGS_STORAGE_KEY);
      window.dispatchEvent(new CustomEvent(NOTIFICATION_SETTINGS_EVENT, { detail: DEFAULT_NOTIFICATION_SETTINGS }));
    } catch {
      // ignore
    }
  }
  return { ...DEFAULT_NOTIFICATION_SETTINGS };
}

export function useNotificationSettings() {
  const [settings, setSettings] = useState<NotificationSettings>(loadNotificationSettings);

  useEffect(() => {
    const handleUpdate = (e: Event) => {
      const customEvent = e as CustomEvent<NotificationSettings>;
      if (customEvent.detail) {
        setSettings(customEvent.detail);
      } else {
        setSettings(loadNotificationSettings());
      }
    };
    window.addEventListener(NOTIFICATION_SETTINGS_EVENT, handleUpdate);
    return () => window.removeEventListener(NOTIFICATION_SETTINGS_EVENT, handleUpdate);
  }, []);

  const updateSettings = useCallback((partial: Partial<NotificationSettings>) => {
    const next = saveNotificationSettings(partial);
    setSettings(next);
  }, []);

  const reset = useCallback(() => {
    const next = resetNotificationSettings();
    setSettings(next);
  }, []);

  return {
    settings,
    updateSettings,
    resetSettings: reset,
  };
}

export const AGENT_CANDIDATES = [
  "claude",
  "codex",
  "gemini",
  "opencode",
  "aider",
  "cursor-agent",
  "droid",
  "crush",
] as const;

export type AgentCandidate = (typeof AGENT_CANDIDATES)[number];

export const AGENTS_SETTINGS_STORAGE_KEY = "ferryx.agents.v1";
export const AGENTS_SETTINGS_CHANGED_EVENT = "ferryx:agents-settings";

export type AgentOverride = {
  enabled?: boolean;
  command?: string;
  args?: string;
};

export type AgentSettings = {
  version: 1;
  defaultAgentId: string | null;
  overrides: Record<string, AgentOverride>;
};

export type ResolvedAgent = {
  name: string;
  available: boolean;
  enabled: boolean;
  command: string;
  args: string;
};

export const DEFAULT_AGENT_SETTINGS: AgentSettings = {
  version: 1,
  defaultAgentId: null,
  overrides: {},
};

function getStorage(storage?: Storage | null): Storage | null {
  if (storage !== undefined) return storage;
  if (typeof window !== "undefined" && window.localStorage) return window.localStorage;
  return null;
}

export function loadAgentSettings(storage?: Storage | null): AgentSettings {
  const store = getStorage(storage);
  if (!store) return { version: 1, defaultAgentId: null, overrides: {} };
  try {
    const raw = store.getItem(AGENTS_SETTINGS_STORAGE_KEY);
    if (!raw) return { version: 1, defaultAgentId: null, overrides: {} };
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return { version: 1, defaultAgentId: null, overrides: {} };

    const defaultAgentId = typeof parsed.defaultAgentId === "string" ? parsed.defaultAgentId : null;
    const rawOverrides = parsed.overrides && typeof parsed.overrides === "object" ? parsed.overrides : {};
    const overrides: Record<string, AgentOverride> = {};

    for (const [key, val] of Object.entries(rawOverrides)) {
      if (!val || typeof val !== "object") continue;
      const entry = val as Partial<AgentOverride>;
      overrides[key] = {
        enabled: typeof entry.enabled === "boolean" ? entry.enabled : undefined,
        command: typeof entry.command === "string" ? entry.command : undefined,
        args: typeof entry.args === "string" ? entry.args : undefined,
      };
    }

    return {
      version: 1,
      defaultAgentId,
      overrides,
    };
  } catch {
    return { version: 1, defaultAgentId: null, overrides: {} };
  }
}

export function saveAgentSettings(settings: AgentSettings, storage?: Storage | null): void {
  const store = getStorage(storage);
  if (!store) return;
  try {
    store.setItem(AGENTS_SETTINGS_STORAGE_KEY, JSON.stringify(settings));
    if (typeof window !== "undefined") {
      window.dispatchEvent(new CustomEvent(AGENTS_SETTINGS_CHANGED_EVENT, { detail: settings }));
    }
  } catch {
    // ignore storage quota / disabled storage
  }
}

export function mergeDetections(
  settings: AgentSettings,
  detections: Array<{ name: string; available: boolean }>,
): ResolvedAgent[] {
  const detectionMap = new Map<string, boolean>();
  if (Array.isArray(detections)) {
    for (const d of detections) {
      if (d && typeof d.name === "string") {
        detectionMap.set(d.name, Boolean(d.available));
      }
    }
  }

  return AGENT_CANDIDATES.map((name) => {
    const available = detectionMap.get(name) ?? false;
    const override = settings?.overrides?.[name];
    const enabled = override?.enabled !== undefined ? override.enabled : available;
    const command = override?.command !== undefined && override.command.trim() !== "" ? override.command : name;
    const args = override?.args ?? "";

    return {
      name,
      available,
      enabled,
      command,
      args,
    };
  });
}

export function getLaunchableAgents(resolved: ResolvedAgent[]): ResolvedAgent[] {
  if (!Array.isArray(resolved)) return [];
  return resolved.filter((agent) => agent.enabled && agent.available);
}

